export default {
  async fetch(request, env, ctx) {
    try {
      const response = await fetch(request);

      // Cuando el túnel está caído, Cloudflare no lanza una excepción de JS:
      // devuelve una respuesta real con status 530 (así envuelve el error 1033).
      // Por eso hay que revisar el código, no solo capturar errores.
      if (response.status === 530) {
        return new Response(PAGINA_INACTIVO, {
          status: 503,
          headers: { "content-type": "text/html;charset=UTF-8" },
        });
      }

      return response;
    } catch (err) {
      // Esto cubre otro tipo de fallas (de red, timeouts, etc.)
      return new Response(PAGINA_INACTIVO, {
        status: 503,
        headers: { "content-type": "text/html;charset=UTF-8" },
      });
    }
  },
};

// Logo embebido en base64 (no una URL): si el túnel está caído, cualquier
// dominio de la app (operativo/pqrs.acbum.com.co) también lo está, así que
// una <img src="https://..."> se rompería justo cuando más se necesita el logo.
const LOGO_BASE64 = "";

const PAGINA_INACTIVO = `<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Fluvi · Servicio temporalmente fuera de línea</title>
<style>
  :root {
    /* Misma paleta de marca que el resto de Fluvi (frontend/tailwind.config.js,
       brand-600 #00487f) y los mismos grises (slate) que usa toda la app. */
    --ink: #0f172a;
    --paper: #f8fafc;
    --muted: #475569;
    --brand-100: #d6e7f4;
    --brand-200: #aecfe9;
    --brand-500: #1f6699;
    --brand-600: #00487f;
    --brand-700: #003a68;
    --amber: #f59e0b;
  }

  @media (prefers-color-scheme: dark) {
    :root {
      --ink: #f1f5f9;
      --paper: #020617;
      --muted: #94a3b8;
    }
  }

  * { box-sizing: border-box; }

  html, body {
    height: 100%;
    margin: 0;
  }

  body {
    background: var(--paper);
    color: var(--ink);
    font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    display: flex;
    flex-direction: column;
    justify-content: center;
    min-height: 100vh;
    position: relative;
    overflow-x: hidden;
  }

  .wordmark {
    position: absolute;
    top: 2.5rem;
    left: 2.5rem;
    display: flex;
    align-items: center;
    gap: 0.75rem;
  }

  .wordmark img {
    width: 40px;
    height: 40px;
    object-fit: contain;
    flex-shrink: 0;
  }

  .wordmark .name {
    display: block;
    font-size: 0.95rem;
    font-weight: 700;
    color: var(--brand-700);
    line-height: 1.25;
  }

  @media (prefers-color-scheme: dark) {
    .wordmark .name { color: var(--brand-200); }
  }

  .wordmark .tag {
    display: block;
    font-size: 0.75rem;
    color: var(--muted);
    max-width: 220px;
    margin-top: 0.1rem;
    line-height: 1.3;
  }

  main {
    position: relative;
    z-index: 2;
    max-width: 640px;
    padding: 8rem 2.5rem 12rem;
  }

  h1 {
    font-weight: 700;
    font-size: clamp(2rem, 5vw, 3rem);
    line-height: 1.15;
    letter-spacing: -0.01em;
    margin: 0 0 1.1rem;
    color: var(--ink);
  }

  p.lead {
    font-size: 1.1rem;
    line-height: 1.6;
    color: var(--muted);
    max-width: 46ch;
    margin: 0 0 2rem;
  }

  .status {
    display: inline-flex;
    align-items: center;
    gap: 0.6rem;
    font-size: 0.95rem;
    color: var(--muted);
    margin-bottom: 2.2rem;
  }

  .dot {
    width: 9px;
    height: 9px;
    border-radius: 50%;
    background: var(--amber);
    flex-shrink: 0;
    animation: pulse 2.2s ease-in-out infinite;
  }

  @keyframes pulse {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.35; }
  }

  button {
    font-family: inherit;
    font-size: 0.95rem;
    font-weight: 600;
    color: #ffffff;
    background: var(--brand-600);
    border: none;
    padding: 0.85rem 1.6rem;
    border-radius: 0.5rem;
    cursor: pointer;
    transition: background 0.15s ease;
  }

  button:hover {
    background: var(--brand-500);
  }

  button:focus-visible {
    outline: 2px solid var(--brand-500);
    outline-offset: 3px;
  }

  p.fallback {
    font-size: 0.85rem;
    color: var(--muted);
    margin-top: 1.2rem;
  }

  .waves {
    position: fixed;
    bottom: 0;
    left: 0;
    width: 100%;
    line-height: 0;
    z-index: 1;
  }

  .waves svg {
    width: 100%;
    height: auto;
    display: block;
  }

  .waves .layer-back {
    animation: drift 26s linear infinite;
  }

  .waves .layer-mid {
    animation: drift 18s linear infinite reverse;
  }

  @keyframes drift {
    from { transform: translateX(0); }
    to   { transform: translateX(-25%); }
  }

  @media (prefers-reduced-motion: reduce) {
    .dot, .waves .layer-back, .waves .layer-mid {
      animation: none;
    }
  }

  @media (max-width: 640px) {
    .wordmark { top: 1.5rem; left: 1.5rem; }
    main { padding: 7rem 1.5rem 9rem; }
    p.lead { font-size: 1rem; }
  }
</style>
</head>
<body>

  <div class="wordmark">
    <img src="data:image/png;base64,${LOGO_BASE64}" alt="Logo ACBUM" />
    <div>
      <span class="name">Acueducto Comunitario Barrios Unidos de Mocoa</span>
      <span class="tag">Fluvi — Sistema de gestión operativa y ambiental</span>
    </div>
  </div>

  <main>
    <h1>Estamos restableciendo el servicio</h1>
    <p class="lead">
      La plataforma está fuera de línea en este momento. Nuestro equipo
      técnico ya está trabajando para restablecer la conexión.
    </p>
    <div class="status">
      <span class="dot" aria-hidden="true"></span>
      Trabajando en ello
    </div>
    <div>
      <button onclick="location.reload()">Reintentar</button>
    </div>
    <p class="fallback">Si el problema continúa, vuelve a intentarlo en unos minutos.</p>
  </main>

  <div class="waves" aria-hidden="true">
    <svg class="layer-back" viewBox="0 0 1440 220" preserveAspectRatio="none" xmlns="http://www.w3.org/2000/svg">
      <path fill="#aecfe9" fill-opacity="0.55"
        d="M0,120 C240,180 480,60 720,100 C960,140 1200,60 1440,110
           L1440,220 L0,220 Z" />
      <path fill="#aecfe9" fill-opacity="0.55"
        d="M1440,120 C1680,180 1920,60 2160,100 C2400,140 2640,60 2880,110
           L2880,220 L1440,220 Z" />
    </svg>
    <svg class="layer-mid" viewBox="0 0 1440 200" preserveAspectRatio="none" xmlns="http://www.w3.org/2000/svg" style="margin-top:-60px;">
      <path fill="#1f6699" fill-opacity="0.75"
        d="M0,100 C200,60 420,150 700,110 C980,70 1220,140 1440,90
           L1440,200 L0,200 Z" />
      <path fill="#1f6699" fill-opacity="0.75"
        d="M1440,100 C1640,60 1860,150 2140,110 C2420,70 2660,140 2880,90
           L2880,200 L1440,200 Z" />
    </svg>
    <svg viewBox="0 0 1440 160" preserveAspectRatio="none" xmlns="http://www.w3.org/2000/svg" style="margin-top:-40px;">
      <path fill="#00487f"
        d="M0,80 C220,40 460,110 720,80 C980,50 1220,100 1440,70
           L1440,160 L0,160 Z" />
    </svg>
  </div>

</body>
</html>`;
